package com.jobradar.taxonomy.location;import java.time.Instant;public record LocationDto(Integer locationId,String city,String state,String country,String displayName,int opportunityCount,boolean active,Instant createdAt,Instant updatedAt){static LocationDto from(LocationEntity e){return new LocationDto(e.getId(),e.getCity(),e.getState(),e.getCountry(),e.getCity()+ (e.getState()==null?"":", "+e.getState())+", "+e.getCountry(),e.getOpportunityCount(),e.isActive(),e.getCreatedAt(),e.getUpdatedAt());}}
